const antyodayaServices=[{name:"Ernakulam–Howrah Antyodaya Express",origin:"Ernakulam Junction",destination:"Howrah Junction",majorStations:["Coimbatore","Chennai","Vijayawada","Bhubaneswar"],regions:["Kerala","Tamil Nadu","Andhra Pradesh","Odisha","West Bengal"],description:"India's first Antyodaya Express service, flagged off in 2016, connecting Kerala to eastern India on a fully unreserved, high-capacity rake."},{name:"Yesvantpur–Garib Nath Antyodaya Express",origin:"Yesvantpur (Bengaluru)",destination:"Garib Nath (Darbhanga)",majorStations:["Guntakal","Nagpur","Varanasi","Patna"],regions:["Karnataka","Andhra Pradesh","Maharashtra","Uttar Pradesh","Bihar"],description:"Connects Bengaluru, a major destination for migrant workers, directly with Darbhanga in Bihar, a key source region."},{name:"Lokmanya Tilak Terminus–Gorakhpur Antyodaya Express",origin:"Lokmanya Tilak Terminus (Mumbai)",destination:"Gorakhpur",majorStations:["Bhusaval","Jabalpur","Lucknow"],regions:["Maharashtra","Madhya Pradesh","Uttar Pradesh"],description:"Links Mumbai's industrial workforce with eastern Uttar Pradesh, one of the country's largest source regions for long-distance migrant travel."},{name:"Anand Vihar–Bhagalpur Antyodaya Express",origin:"Anand Vihar Terminal (Delhi)",destination:"Bhagalpur",majorStations:["Kanpur","Lucknow","Chhapra"],regions:["Delhi","Uttar Pradesh","Bihar"],description:"A fully unreserved superfast link between the national capital and eastern Bihar, serving one of India's busiest labour-migration corridors."}];document.addEventListener("DOMContentLoaded",()=>{const e=[{label:"Introduced",value:"2016"},{label:"Service Type",value:"Superfast, Unreserved"},{label:"Coach Class",value:"High-Capacity General"},{label:"First Route",value:"Ernakulam – Howrah"}],a=document.getElementById("quick-facts-container");a&&e.forEach(e=>{const n=document.createElement("div");n.className="fact-card",n.innerHTML=`\n                <div class="fact-label">${e.label}</div>\n                <div class="fact-value">${e.value}</div>\n            `,a.appendChild(n)});const n=[{year:"2016",title:"Concept Announced",description:"Antyodaya Express was announced in the Railway Budget 2016–17 by Railway Minister Suresh Prabhu, aimed at providing safe, high-capacity unreserved travel."},{year:"2016",title:"Inaugural Run",description:"The first Antyodaya Express was flagged off between Ernakulam Junction in Kerala and Howrah Junction in West Bengal."},{year:"2016–2018",title:"Network Expansion",description:"New Antyodaya services were introduced on other high-demand unreserved corridors, connecting major employment hubs with migrant-labour source regions."},{year:"Present",title:"Ongoing Service",description:"Antyodaya Express services continue to operate on select long-distance routes, offering a dedicated high-capacity unreserved alternative to standard general coaches."}],i=document.getElementById("timeline-container");i&&n.forEach(e=>{const a=document.createElement("div");a.className="timeline-item",a.tabIndex=0,a.innerHTML=`\n                <div class="timeline-year">${e.year}</div>\n                <div class="timeline-content">\n                    <h3>${e.title}</h3>\n                    <p>${e.description}</p>\n                </div>\n            `,i.appendChild(a)});const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-item").forEach(e=>t.observe(e));const r=[{title:"High-Capacity Coaches",description:"Every coach is a purpose-built, high-capacity unreserved (General) coach, seating and accommodating significantly more passengers than a standard general coach."},{title:"LHB Coach Platform",description:"Built on the Linke Hofmann Busch (LHB) platform, offering anti-telescopic safety features and a smoother, higher-speed-capable ride."},{title:"Wider Doorways",description:"Coaches feature wider doorways designed for faster, safer boarding and deboarding on busy unreserved platforms."}],s=document.getElementById("features-container");s&&r.forEach(e=>{const a=document.createElement("div");a.className="feature-card",a.tabIndex=0,a.innerHTML=`\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            `,s.appendChild(a)});const o=document.getElementById("services-container");o&&(o.innerHTML=antyodayaServices.map(e=>`\n            <div class="service-card" tabindex="0">\n                <h3>${e.name}</h3>\n                <div class="service-route">${e.origin} → ${e.destination}</div>\n                <div class="service-stations"><strong>Via:</strong> ${e.majorStations.join(", ")}</div>\n                <p class="service-desc">${e.description}</p>\n            </div>\n        `).join(""));const d=document.getElementById("routes-container");d&&(d.innerHTML=antyodayaServices.map(e=>`\n            <div class="route-card">\n                <div>\n                    <div class="origin-dest">${e.origin} → ${e.destination}</div>\n                    <div class="stations"><strong>Via:</strong> ${e.majorStations.join(", ")}</div>\n                </div>\n                <div class="regions-tag">${e.regions.join(" · ")}</div>\n            </div>\n        `).join(""));const c=[{icon:"💺",title:"High-Capacity Seating",description:"High-density unreserved seating designed to safely accommodate more passengers than a conventional general coach."},{icon:"🔌",title:"Charging Points",description:"Mobile charging points fitted in the coaches — a notable first for unreserved-class travel in India."},{icon:"🚰",title:"Drinking Water",description:"Onboard drinking water facilities, with RO water points provided at many originating and major stations."},{icon:"📢",title:"Passenger Information",description:"Station announcements and coach signage help passengers track the journey on long, multi-state routes."},{icon:"🚻",title:"Bio-Toilets",description:"Coaches are fitted with zero-discharge bio-toilets, improving hygiene compared to older-style general coaches."},{icon:"🛡️",title:"Safety Features",description:"CCTV coverage, fire-retardant materials and LED lighting are standard across Antyodaya Express rakes."}],l=document.getElementById("facilities-container");l&&c.forEach(e=>{const a=document.createElement("div");a.className="facility-card",a.tabIndex=0,a.innerHTML=`\n                <div class="facility-icon" aria-hidden="true">${e.icon}</div>\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            `,l.appendChild(a)});const h=['"Antyodaya" means the upliftment of the last and most disadvantaged person, a philosophy also behind India\'s Antyodaya Anna Yojana welfare scheme.',"Antyodaya Express was among the first Indian Railways services to fit mobile charging points inside fully unreserved coaches.","The first Antyodaya Express connected Ernakulam in Kerala with Howrah in West Bengal, spanning several states along India's eastern and southern coasts."],g=document.getElementById("trivia-container");g&&h.forEach(e=>{const a=document.createElement("div");a.className="trivia-card",a.tabIndex=0,a.innerHTML=`<p>${e}</p>`,g.appendChild(a)})});